      var totalLogos;
    var current = [0, 1, 2, 3, 4];
    var lastframe = -1;

    function updateLogos() {
        var randLogo = Math.floor(Math.random() * 5);
        if (randLogo == lastframe) {
            updateLogos();
            return
        }
        updateLogo(randLogo);
        lastframe = randLogo;
        TweenMax.delayedCall(2, updateLogos);
    }

    function updateLogo(num) {
        var nextImage = Math.floor(Math.random() * totalLogos);

        for (var i = 0; i < 5; i++) {
            if (nextImage == current[i]) {
                updateLogo(num);
                return
            }
        }

        for (var i = 0; i < totalLogos; i++) {
            var logo = document.querySelectorAll('.cCompanyLogosContainer')[num].querySelectorAll('.cCompanyLogo')[i];

            if (logo.style.opacity > .5) {
                if (nextImage == i) {
                    updateLogo(num);
                    return
                }
                TweenMax.to(logo, .75, {
                    autoAlpha: 0
                });
            } else {
                if (nextImage == i) {
                    TweenMax.to(logo, .75, {
                        autoAlpha: 1,
                        delay: .25
                    });
                    current[num] = i;
                }
            }
        }
    }

    document.addEventListener("DOMContentLoaded", function() {
        totalLogos = document.querySelector('.cCompanyLogosContainer').querySelectorAll(".cCompanyLogo").length;
        TweenMax.set('.cCompanyLogo', {
            autoAlpha: 0
        });
        for (var j = 0; j < 5; j++) {
            for (var i = 0; i < totalLogos; i++) {
                if (j == i && i < 5) {
                    TweenMax.set(document.querySelectorAll('.cCompanyLogosContainer')[j].querySelectorAll('.cCompanyLogo')[i], {
                        autoAlpha: 1
                    });
                }
            }
        }
        TweenMax.delayedCall(1, updateLogos);
    });

